import{_ as a,o as r,c as i,a4 as t}from"./chunks/framework.BE47AOxC.js";const p=JSON.parse('{"title":"Version v0.11.2","description":"Notes de la version v0.11.2 de Teuthis-CMS.","frontmatter":{"title":"Version v0.11.2","description":"Notes de la version v0.11.2 de Teuthis-CMS."},"headers":[],"relativePath":"versions/v0-11-2.md","filePath":"versions/v0-11-2.md"}'),s={name:"versions/v0-11-2.md"};function o(l,e,n,u,d,c){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="version-v0-11-2" tabindex="-1">Version v0.11.2 <a class="header-anchor" href="#version-v0-11-2" aria-label="Permalink to &quot;Version v0.11.2&quot;">​</a></h1><p>Publiée le 5 novembre 2026. <a href="https://github.com/Bastien-OC20/calamars/releases/tag/v0.11.2" target="_blank" rel="noreferrer">La release sur GitHub</a>.</p><blockquote><p><strong>Version non distribuée, remplacée par la <a href="https://github.com/Bastien-OC20/calamars/releases/tag/v0.11.3" target="_blank" rel="noreferrer">v0.11.3</a>.</strong> Ses images sont sur GHCR, vérifiées et signées, mais la publication s&#39;est arrêtée avant le dépôt de distribution (erreurs passagères de l&#39;API de GitHub, voir l&#39;ADR-0076) : aucune instance ne peut s&#39;y mettre à jour.</p></blockquote><h2 id="v0-11-2-—-2026-11-05" tabindex="-1">v0.11.2 — 2026-11-05 <a class="header-anchor" href="#v0-11-2-—-2026-11-05" aria-label="Permalink to &quot;v0.11.2 — 2026-11-05&quot;">​</a></h2><h3 id="nouveautes" tabindex="-1">Nouveautés <a class="header-anchor" href="#nouveautes" aria-label="Permalink to &quot;Nouveautés&quot;">​</a></h3><ul><li>L&#39;archive de la pile et l&#39;installateur sont signés par cosign (fichiers <code>.sigstore.json</code>) ; la commande <code>teuthis</code> et l&#39;installateur vérifient la signature de l&#39;archive avant de l&#39;ouvrir, si cosign v3 est installé sur le serveur.</li><li>Chaque image est construite une seule fois : c&#39;est l&#39;image essayée et analysée qui est signée, puis étiquetée. Une étiquette de version n&#39;est jamais republiée.</li></ul><h3 id="corrections" tabindex="-1">Corrections <a class="header-anchor" href="#corrections" aria-label="Permalink to &quot;Corrections&quot;">​</a></h3><ul><li>Images : correctif de sécurité de zlib (CVE-2026-85091), présent dans les images 0.11.1.</li><li>API : pypdf 6.21.4, qui corrige des dénis de service sur un PDF piégé.</li></ul><h3 id="a-faire-par-l-exploitant" tabindex="-1">À faire par l&#39;exploitant <a class="header-anchor" href="#a-faire-par-l-exploitant" aria-label="Permalink to &quot;À faire par l&#39;exploitant&quot;">​</a></h3><p>Mettre à jour : <code>sudo teuthis mettre-a-jour</code> (sauvegarde d&#39;abord, retour arrière automatique).</p><ul><li>Recommandé : installer cosign v3 sur le serveur ; sans lui, ni la signature des images ni celle de l&#39;archive ne sont vérifiées.</li><li>Pour ce premier passage, la commande 0.11.1 ne vérifie pas la signature de l&#39;archive : pour qu&#39;il le soit, suivez une fois la méthode manuelle de <code>deploy/LISEZMOI.md</code> (« Mettre à jour », étape <code>cosign verify-blob</code>).</li></ul>',11)])])}const h=a(s,[["render",o]]);export{p as __pageData,h as default};
